/* ============================================
   INPUT COMPONENT
   Text input with label, icons, and helper text
   ============================================ */

.ds-input {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
  width: 100%;
}

/* ============================================
   FIELD WRAPPER
   ============================================ */

.ds-input__field-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

/* ============================================
   FIELD
   ============================================ */

.ds-input__field {
  width: 100%;
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-input-bg-primary);

  /* Typography */
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-input-text-primary);

  /* Transitions */
  transition: border-color var(--motion-duration-base) var(--motion-ease-standard), background-color var(--motion-duration-base) var(--motion-ease-standard);
  outline: none;
  /* The row height, border included (--control-height-*). */
  box-sizing: border-box;
  height: var(--control-height-default);
  padding-block: 0;
}

.ds-input__field::placeholder {
  color: var(--color-input-text-placeholder);
}

.ds-input__field:hover:not(:focus):not(:disabled) {
  border-color: var(--color-input-border-hover);
}

.ds-input__field:focus {
  border-color: var(--color-input-border-selected);
  background-color: var(--color-input-bg-primary);
}

/* ============================================
   ICONS
   ============================================ */

.ds-input__icon {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  pointer-events: none;
}

.ds-input__icon--left {
  inset-inline-start: var(--padding-400); /* 16px */
}

.ds-input__icon--right {
  inset-inline-end: var(--padding-400); /* 16px */
}

.ds-input--has-icon-left .ds-input__field {
  padding-inline-start: calc(var(--padding-400) + 24px + var(--gap-200)); /* 16px + 24px icon + 8px gap */
}

.ds-input--has-icon-right .ds-input__field {
  padding-inline-end: calc(var(--padding-400) + 24px + var(--gap-200)); /* 16px + 24px icon + 8px gap */
}

/* ============================================
   ERROR STATE
   ============================================ */

.ds-input--error .ds-input__field {
  border-color: var(--color-status-error-border);
}

.ds-input--error .ds-input__field:focus {
  border-color: var(--color-status-error-border);
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-input--disabled .ds-input__field {
  background-color: var(--color-input-bg-disabled);
  border-color: var(--color-input-border-disabled);
  color: var(--color-input-text-disabled);
  cursor: not-allowed;
}

.ds-input--disabled .ds-input__field::placeholder {
  color: var(--color-input-text-disabled);
}

.ds-input--disabled .ds-input__icon {
  color: var(--color-input-text-disabled);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-input--compact .ds-input__field {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  height: var(--control-height-compact);
  padding-block: 0;
}

.ds-input--compact .ds-input__icon {
  --icon-size: var(--icon-size-500);
}

.ds-input--compact .ds-input__icon--left {
  inset-inline-start: var(--padding-300); /* 12px */
}

.ds-input--compact .ds-input__icon--right {
  inset-inline-end: var(--padding-300); /* 12px */
}

.ds-input--compact.ds-input--has-icon-left .ds-input__field {
  padding-inline-start: calc(var(--padding-300) + 20px + var(--gap-200)); /* 12px + 20px icon + 8px gap */
}

.ds-input--compact.ds-input--has-icon-right .ds-input__field {
  padding-inline-end: calc(var(--padding-300) + 20px + var(--gap-200)); /* 12px + 20px icon + 8px gap */
}


/* ============================================
   AFFIXED: a prefix, a suffix or a clear button
   The wrapper becomes the field's box (border,
   fill, hover, focus, error, disabled), and the
   native input inside it a bare, growing text
   run, so an affix of any width sits on the
   field's line with no padding to guess. Only
   in this mode: an input without affixes keeps
   its border on the <input> exactly as before.
   ============================================ */

.ds-input--affixed .ds-input__field-wrapper {
  gap: var(--gap-200);
  box-sizing: border-box;
  height: var(--control-height-default);
  padding-inline: var(--padding-400);
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300);
  background-color: var(--color-input-bg-primary);
  transition: border-color var(--motion-duration-base) var(--motion-ease-standard), background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-input--affixed .ds-input__field-wrapper:hover:not(:focus-within) {
  border-color: var(--color-input-border-hover);
}

.ds-input--affixed .ds-input__field-wrapper:focus-within {
  border-color: var(--color-input-border-selected);
}

.ds-input--affixed .ds-input__field,
.ds-input--affixed .ds-input__field:hover,
.ds-input--affixed .ds-input__field:focus {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: none;
  border-radius: 0;
  background-color: transparent;
}

.ds-input--affixed .ds-input__icon {
  position: static;
  transform: none;
  flex-shrink: 0;
}

.ds-input--affixed.ds-input--has-icon-left .ds-input__field,
.ds-input--affixed.ds-input--has-icon-right .ds-input__field {
  padding-inline: 0;
}

.ds-input__affix {
  flex-shrink: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
  white-space: nowrap;
}

/* The clear button and an action sit a step in from the edge, their circles centred in the row. */
.ds-input__action {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  margin-inline-end: calc(-1 * var(--padding-200));
}

.ds-input--affixed.ds-input--compact .ds-input__action {
  margin-inline-end: calc(-1 * var(--padding-300));
}

.ds-input__action + .ds-input__clear {
  margin-inline-start: calc(-1 * var(--gap-200));
}

.ds-input__clear {
  flex-shrink: 0;
  margin-inline-end: calc(-1 * var(--padding-200));
}

.ds-input--affixed.ds-input--error .ds-input__field-wrapper,
.ds-input--affixed.ds-input--error .ds-input__field-wrapper:focus-within {
  border-color: var(--color-status-error-border);
}

.ds-input--affixed.ds-input--disabled .ds-input__field-wrapper {
  background-color: var(--color-input-bg-disabled);
  border-color: var(--color-input-border-disabled);
  cursor: not-allowed;
}

.ds-input--affixed.ds-input--disabled .ds-input__field {
  background-color: transparent;
  border: none;
}

.ds-input--affixed.ds-input--disabled .ds-input__affix {
  color: var(--color-input-text-disabled);
}

.ds-input--affixed.ds-input--compact .ds-input__field-wrapper {
  height: var(--control-height-compact);
  padding-inline: var(--padding-300);
}

.ds-input--affixed.ds-input--compact .ds-input__affix {
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-input--affixed.ds-input--compact .ds-input__clear {
  margin-inline-end: calc(-1 * var(--padding-300));
}

'use client';

import React, { useRef, useState } from 'react';
import { Field } from '../Field/Field';
import { CircularButton } from '../CircularButton/CircularButton';
import './Input.css';
import '../../fonts/material-symbols.css';
import { mirrorClass } from '../../behaviors/direction';

/** Props owned by Input itself — everything else falls through to the <input>. */
type InputOwnProps = {
  /** Input label text */
  label?: string;
  /** Current value */
  value?: string;
  /** Input type — curated subset; use a dedicated component for checkbox/radio/file */
  type?: 'text' | 'email' | 'password' | 'number' | 'search' | 'tel' | 'url';
  /** Component size (not the native character-width `size` attribute) */
  size?: 'default' | 'compact';
  /** Error state — shows error styling and message */
  error?: boolean;
  /** Helper text displayed below the input. With the older `error` flag and no `errorText`, it doubles as the error message. */
  helperText?: string;
  /** The error message, shown under the input while the helper text keeps its place. Setting it marks the input invalid; Field's spec owns the wiring. */
  errorText?: React.ReactNode;
  /**
   * Text or a node inside the field before the value, read by a screen reader
   * as part of the field (a currency symbol, `https://`, a country code). Not
   * the decorative `iconLeft`.
   */
  prefix?: React.ReactNode;
  /** Text or a node inside the field after the value, read by a screen reader as part of the field (a unit, `.com`, `%`). Not the decorative `iconRight`. */
  suffix?: React.ReactNode;
  /** A control inside the field at its end, after the suffix: a show/hide button, a copy button. Unlike `suffix` it is not read as part of the field; it is a control of its own. */
  action?: React.ReactNode;
  /** Show a clear button while the field holds a value. It empties the field, fires `onChange` and `onValueChange` with an empty value, then `onClear`, and returns focus to the field. */
  clearable?: boolean;
  /** Accessible name of the clear button. Defaults to "Clear". */
  clearLabel?: string;
  /** Called after the clear button empties the field. */
  onClear?: () => void;
  /** Leading icon — Material Symbol name (string) or custom element (ReactNode) */
  iconLeft?: string | React.ReactNode;
  /** Trailing icon — Material Symbol name (string) or custom element (ReactNode) */
  iconRight?: string | React.ReactNode;
  /**
   * Convenience callback receiving the value directly.
   * Fires alongside `onChange`, which keeps the standard React event signature
   * so form libraries (react-hook-form, Formik, TanStack Form) work unmodified.
   */
  onValueChange?: (value: string) => void;
  /** Additional CSS classes — applied to the wrapper, not the <input> */
  className?: string;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
};

export interface InputProps
  extends InputOwnProps,
    Omit<React.ComponentPropsWithoutRef<'input'>, keyof InputOwnProps> {}

/**
 * Text input with optional label, helper text, icons and error state.
 *
 * Forwards a ref to the underlying `<input>` and spreads unrecognised props onto
 * it, so `autoComplete`, `maxLength`, `inputMode`, `data-*` and form-library
 * registration all work.
 */
export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      label,
      placeholder = '',
      value,
      type = 'text',
      size = 'default',
      disabled = false,
      required = false,
      error = false,
      helperText,
      errorText,
      prefix,
      suffix,
      action,
      clearable = false,
      clearLabel = 'Clear',
      onClear,
      iconLeft,
      iconRight,
      onChange,
      onValueChange,
      className = '',
      ariaLabel,
      name,
      id,
      defaultValue,
      readOnly,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-input';
    const innerRef = useRef<HTMLInputElement | null>(null);
    const setRef = (node: HTMLInputElement | null) => {
      innerRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };
    // Whether an uncontrolled field holds a value, so the clear button knows
    // when to show; a controlled one reads `value`.
    const [uncontrolledFilled, setUncontrolledFilled] = useState(
      defaultValue != null && String(defaultValue) !== '',
    );
    const filled = value !== undefined ? value !== '' && value != null : uncontrolledFilled;
    const hasErrorText = errorText != null && errorText !== false && errorText !== '';
    const invalid = error || hasErrorText;
    const hasPrefix = prefix != null && prefix !== false && prefix !== '';
    const hasSuffix = suffix != null && suffix !== false && suffix !== '';
    const hasAction = action != null && action !== false;
    const affixed = hasPrefix || hasSuffix || clearable || hasAction;
    const showClear = clearable && filled && !disabled && !readOnly;

    const classes = [
      baseClass,
      size === 'compact' ? `${baseClass}--compact` : '',
      invalid ? `${baseClass}--error` : '',
      affixed ? `${baseClass}--affixed` : '',
      disabled ? `${baseClass}--disabled` : '',
      iconLeft ? `${baseClass}--has-icon-left` : '',
      iconRight ? `${baseClass}--has-icon-right` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (value === undefined) setUncontrolledFilled(e.target.value !== '');
      onChange?.(e);
      onValueChange?.(e.target.value);
    };

    /* Empty the field the way typing would: set the native value and fire an
       input event, so React's onChange (and a form library listening to it)
       hears the change whether the field is controlled or not. */
    const handleClear = () => {
      const input = innerRef.current;
      if (!input) return;
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set;
      setter?.call(input, '');
      input.dispatchEvent(new Event('input', { bubbles: true }));
      onClear?.();
      input.focus();
    };

    // Keep the historical id derivation — Field only generates one as a
    // fallback, so an explicit id/name/label still wins and existing markup
    // (and any consumer's own htmlFor) is unchanged.
    const inputId = id || name || label?.toLowerCase().replace(/\s+/g, '-');
    /* A consumer's aria-describedby joins the helper id rather than losing to it. */
    /* The prefix and suffix are read as part of the field, so they join it too. */
    const prefixId = hasPrefix ? `${inputId}-prefix` : undefined;
    const suffixId = hasSuffix ? `${inputId}-suffix` : undefined;
    const describedBy =
      [
        rest['aria-describedby'],
        prefixId,
        suffixId,
        hasErrorText ? `${inputId}-error` : undefined,
        helperText ? `${inputId}-helper` : undefined,
      ]
        .filter(Boolean)
        .join(' ') || undefined;

    return (
      <Field
        className={classes}
        label={label}
        helperText={helperText}
        errorText={errorText}
        error={error}
        required={required}
        disabled={disabled}
        size={size}
        id={inputId}
      >
        <div className={`${baseClass}__field-wrapper`}>
          {iconLeft && (
            <span
              className={`${baseClass}__icon ${baseClass}__icon--left${typeof iconLeft === 'string' ? ` material-symbols-rounded ${mirrorClass(iconLeft)}` : ''}`}
              aria-hidden="true"
            >
              {iconLeft}
            </span>
          )}
          {hasPrefix && (
            <span className={`${baseClass}__affix ${baseClass}__affix--prefix`} id={prefixId} dir="auto">
              {prefix}
            </span>
          )}
          <input
            {...rest}
            ref={setRef}
            className={`${baseClass}__field`}
            type={type}
            id={inputId}
            name={name}
            value={value}
            defaultValue={defaultValue}
            readOnly={readOnly}
            placeholder={placeholder}
            disabled={disabled}
            required={required}
            aria-label={rest['aria-label'] ?? ariaLabel ?? label}
            aria-invalid={invalid}
            aria-describedby={describedBy}
            onChange={handleChange}
          />
          {hasSuffix && (
            <span className={`${baseClass}__affix ${baseClass}__affix--suffix`} id={suffixId} dir="auto">
              {suffix}
            </span>
          )}
          {hasAction && <span className={`${baseClass}__action`}>{action}</span>}
          {showClear && (
            <CircularButton
              className={`${baseClass}__clear`}
              icon="close"
              variant="tertiary"
              size="compact"
              ariaLabel={clearLabel}
              onClick={handleClear}
            />
          )}
          {iconRight && (
            <span
              className={`${baseClass}__icon ${baseClass}__icon--right${typeof iconRight === 'string' ? ` material-symbols-rounded ${mirrorClass(iconRight)}` : ''}`}
              aria-hidden="true"
            >
              {iconRight}
            </span>
          )}
        </div>
      </Field>
    );
  },
);

Input.displayName = 'Input';
